import {uid,money,toCents,localDate,dayDate,makeTrip,makeDemo,ledger,parseBackup,encodeShare,decodeShare} from './domain.js';
import {createConversation} from './conversation-ui.js?v=0.4.0';
import {createDiscovery} from './discovery-ui.js?v=0.4.0';
import {createMapFeature} from './maps-ui.js?v=0.4.0';
import {validPlace} from './place-schema.js';

const paths={
  sparkles:'m12 3 2.4 6.6L21 12l-6.6 2.4L12 21l-2.4-6.6L3 12l6.6-2.4L12 3Z M20 2v4m-2-2h4',
  mountain:'m3 19 7-12 4 7 3-5 4 10H3Z M7 12l3 3 3-3',calendar:'M8 2v4m8-4v4M3 10h18M5 4h14a2 2 0 0 1 2 2v14H3V6a2 2 0 0 1 2-2Z',
  pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Z M15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0Z',wallet:'M20 8H5a2 2 0 0 1 0-4h13v4m2 0H5a2 2 0 0 1-2-2v14h17V8Zm-5 4h6v5h-6v-5Z',
  check:'M9 4H5v17h14V4h-4M9 2h6v5H9V2Zm-2 12 3 3 7-7',user:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0ZM4 21v-2a8 8 0 0 1 16 0v2',plus:'M12 5v14M5 12h14',
  close:'m6 6 12 12M6 18 18 6',chevron:'m9 5 7 7-7 7',share:'M12 16V2m-4 4 4-4 4 4M7 9H4v12h16V9h-3',settings:'M12 8a4 4 0 1 1 0 8 4 4 0 0 1 0-8ZM9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1 1-3Z',
  info:'M12 11v6m0-10v.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z',food:'M4 3v7m3-7v7m3-7v7m-6 0h6m-3 0v11M19 3c-4 4-5 9 0 9V3Zm0 9v9',bed:'M3 5v16m18-7v7M3 17h18M3 10h6v7m0-5h9a3 3 0 0 1 3 3v2',
  bus:'M5 4h14v14H5V4Zm0 9h14M9 4v9m6-9v9M8 21v-3m8 3v-3M8 16h.01M16 16h.01',bag:'M4 7h16v14H4V7Zm4 0V5a4 4 0 0 1 8 0v2',coins:'M20 7c0 2-4 3-8 3S4 9 4 7s4-3 8-3 8 1 8 3ZM4 7v10c0 2 4 3 8 3s8-1 8-3V7M4 12c0 2 4 3 8 3s8-1 8-3',
  trash:'M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7',edit:'m15 5 4 4M4 20l1-6L17 2l5 5L10 19l-6 1Z',up:'m5 15 7-7 7 7',down:'m5 9 7 7 7-7',download:'M12 3v12m-5-5 5 5 5-5M3 17v4h18v-4',upload:'M12 16V3M7 8l5-5 5 5M3 17v4h18v-4',heart:'M20 4c-3-2-6 0-8 2-2-2-5-4-8-2-5 4 0 10 8 16 8-6 13-12 8-16Z',save:'m4 12 5 5L20 6',arrow:'M5 12h14m-5-5 5 5-5 5',clock:'M12 6v6l4 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z',copy:'M9 9h12v12H9V9ZM5 15H3V3h12v2',print:'M6 9V3h12v6M6 17H3V9h18v8h-3M6 14h12v7H6v-7Z',sun:'M12 2v2m0 16v2M2 12h2m16 0h2M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2M17 12a5 5 0 1 1-10 0 5 5 0 0 1 10 0Z'
};
const icon=(name,small=false)=>`<svg aria-hidden="true" class="icon ${small?'small-icon':''}" viewBox="0 0 24 24"><path d="${paths[name]||paths.pin}"/></svg>`;
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(label,action,style='secondary',symbol='',extra='')=>`<button type="button" class="btn ${style}" data-action="${action}" ${extra}>${symbol?icon(symbol):''}${e(label)}</button>`;
const ib=(symbol,label,action,extra='')=>`<button type="button" class="icon-btn" aria-label="${e(label)}" data-action="${action}" ${extra}>${icon(symbol)}</button>`;
const empty=(title,note,symbol='mountain')=>`<div class="empty">${icon(symbol)}<strong>${e(title)}</strong><p class="small">${e(note)}</p></div>`;
const KEY='lvce.travel.v1';const app=document.querySelector('#app'),sheet=document.querySelector('#sheet');
let state,tab='trip',day=0,ordering=false,filter='全部',saved=true,recovery=false,readonly=null,toastTimer;
try { const raw=localStorage.getItem(KEY);state=raw?parseBackup(raw):null; } catch {recovery=true;}
if(!state){const demo=makeDemo();state={version:1,trips:[demo],activeId:demo.id};}
if(location.hash.startsWith('#share='))try{readonly=decodeShare(location.hash.slice(7));}catch{recovery=true;}
const trip=()=>state.trips.find(t=>t.id===state.activeId)??state.trips[0];
function toast(message){const n=document.querySelector('#toast');n.textContent=message;n.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>n.classList.remove('show'),3600);}
function persist(message){
  try{if(recovery){const raw=localStorage.getItem(KEY);if(raw)localStorage.setItem(`${KEY}.recovery`,raw);recovery=false;}localStorage.setItem(KEY,JSON.stringify(state));saved=true;if(message)toast(message);}
  catch{saved=false;toast('暂时无法保存到设备，请到「我的」导出备份');}
  render();
}
const navs=[['trip','calendar','行程'],['ask','sparkles','问 AI'],['discover','food','美食·住宿'],['budget','wallet','记账'],['check','check','清单'],['mine','user','我的']];
function nav(desktop=false){return `<${desktop?'div':'nav'} class="${desktop?'aside-links':'nav'}" aria-label="主导航"><div class="${desktop?'stack':'nav-inner'}">${navs.map(([id,symbol,label])=>`<button type="button" class="${tab===id?'active':''}" data-action="nav" data-tab="${id}" ${tab===id?'aria-current="page"':''}><span class="nav-icon">${icon(symbol)}</span>${label}</button>`).join('')}</div></${desktop?'div':'nav'}>`;}
function topbar(){return `<header class="topbar"><a class="brand" href="./" aria-label="旅策首页"><img src="./icon.svg" alt="">旅策 <span class="desktop-only">/</span><span class="kicker muted">把计划装进口袋，安心出发</span></a><div class="row"><span class="save-indicator ${saved?'':'amber'}">${icon(saved?'save':'info')}${saved?'保存在此设备':'尚未保存'}</span>${ib('settings','旅行与设置','nav','data-tab="mine"')}</div></header>`;}
function dayTabs(){return `<div class="tabs" role="group" aria-label="选择旅行日期">${trip().days.map((d,i)=>`<button type="button" class="tab ${day===i?'active':''}" data-action="day" data-day="${i}" aria-pressed="${day===i}">Day ${i+1} ${e(d.title)}</button>`).join('')}</div>`;}
function stopCard(x,i){return `<article class="stop"><div class="stop-time">${e(x.time)}</div><div class="stop-card"><div class="stop-heading"><div class="stop-symbol">${icon(x.type==='餐饮'?'food':x.type==='住宿'?'bed':x.type==='交通'?'bus':'mountain')}</div><div class="stop-body"><h3>${e(x.title)}</h3><div class="stop-detail">${e(x.note||`${x.type} · 停留 ${x.duration} 分钟`)}</div></div></div><div class="stop-footer"><span class="pill">${x.cost?`预计 ${money(x.cost)} / 人`:'未计费用'} · ${x.duration} 分钟</span>${ordering?`<div class="order-controls">${ib('up',`上移${x.title}`,'move','data-id="'+e(x.id)+'" data-dir="-1" '+(i===0?'disabled':''))}${ib('down',`下移${x.title}`,'move','data-id="'+e(x.id)+'" data-dir="1" '+(i===trip().days[day].items.length-1?'disabled':''))}</div>`:btn('编辑','edit-stop','text','edit',`data-id="${e(x.id)}"`)}</div></div></article>`;}
function tripPage(){const t=trip(),d=t.days[day],est=d.items.reduce((sum,x)=>sum+x.cost,0);return `<section class="trip-page"><div class="page-head"><div><h1>${e(t.title)}</h1><p class="muted">${e(t.city)} · ${e(t.date)} · ${t.days.length} 天 · ${t.members.length} 人同行</p></div><div class="row">${btn('问 AI','ask-open','soft','sparkles')}${ib('share','分享旅行计划','share')}</div></div>${t.demo?`<div class="banner-sample"><span>当前为杭州示例，可直接编辑体验</span>${btn('新建旅行','new-trip','text')}</div>`:''}${dayTabs()}<div class="layout trip-layout"><div class="map-panel">${maps.panel(t,day)}</div><div><div class="day-title"><div><h2>第 ${day+1} 天 · ${e(d.title)}</h2><p class="hint">${e(dayDate(t.date,day))} · ${d.items.length} 个安排</p></div>${btn('问 AI 调整','ask-ai-adjust','soft','sparkles')}</div><div class="timeline">${d.items.length?d.items.map((x,i)=>stopCard(x,i)+`<div class="stop-place-line">${x.place&&validPlace(x.place)?`<span class="hint">${icon('pin',true)}${e(x.place.address)}</span>`:btn('在地图上确认地点','maps-match','text','pin',`data-id="${e(x.id)}"`)}</div>`).join(''):empty('留白的一天','添加地点，或问 AI 安排一天的行程。')}</div><div class="action-bar sticky-actions">${btn('搜索地点','maps-search','primary','pin')}${btn('手动添加','add-stop','secondary','plus')}${btn(ordering?'完成排序':'调整顺序','order',ordering?'soft':'secondary',ordering?'save':'edit')}</div><div class="note">${icon('info')}<div><strong>当天已列预计人均 ${money(est)}</strong><p class="hint">预计费用不自动计入实际账单；道路、开放与预约信息出发前请核实。</p></div></div></div></div></section>`;}

function budgetPage(){const t=trip(),l=ledger(t),totalBudget=t.budget*t.members.length,remaining=totalBudget-l.total,percent=Math.round(l.total/totalBudget*100);return `<section><div class="page-head"><div><h1>每一笔，都算得清</h1><p class="muted">${e(t.title)} · ${t.members.length} 人 · 人民币</p></div>${ib('info','查看分摊规则','budget-info')}</div><div class="budget-layout"><div class="stack"><div class="budget-card"><p>已记录支出</p><div class="big-money">${money(l.total)}</div><div class="row" style="gap:14px"><div class="progress" style="flex:1"><span style="width:${Math.min(percent,100)}%"></span></div><span class="small">${percent}%</span></div><div class="budget-bottom"><span>总预算 ${money(totalBudget)}</span><span>${remaining<0?'已超支':'剩余'} ${money(Math.abs(remaining))}</span></div></div><div class="card flat"><h2>谁该付给谁</h2>${l.transfers.length?l.transfers.map(x=>`<div class="settle-row"><div><strong>${e(x.from)} ${icon('arrow',true)} ${e(x.to)}</strong><p class="hint">按实际参与人均分</p></div><strong>${money(x.cents)}</strong></div>`).join(''):`<div class="settle-row"><div><strong>${l.total?'大家已经付得刚刚好':'还没有共同开销'}</strong><p class="hint">${l.total?'当前账单无需转账结算':'记下第一笔，自动算清分摊。'}</p></div>${icon('save')}</div>`}${btn('查看结算明细','settle','text','coins')}</div></div><div class="stack"><div class="card-head" style="margin:0"><h2>消费记录 <span class="count-badge">${t.expenses.length}</span></h2><span class="hint">${t.demo?'示例账单':'按消费日期排列'}</span></div><div class="expense-list">${t.expenses.length?[...t.expenses].sort((a,b)=>b.date.localeCompare(a.date)).map(x=>`<div class="expense-row">${icon(x.type==='住宿'?'bed':x.type==='餐饮'?'food':x.type==='交通'?'bus':x.type==='购物'?'bag':'coins')}<div class="expense-title"><h3>${e(x.title)}</h3><p>${e(t.members.find(m=>m.id===x.payer)?.name)}付款 · ${x.participants.length} 人分摊 · ${e(x.date.slice(5))}</p></div><span class="amount">${money(x.cents)}</span>${ib('edit',`编辑消费${x.title}`,'edit-expense',`data-id="${e(x.id)}"`)}</div>`).join(''):empty('第一笔开销，从这里开始','车票、午餐，或者一间喜欢的民宿。','wallet')}</div><div class="action-bar sticky-actions" style="margin:0">${btn('记一笔','add-expense','primary full','plus')}</div><p class="hint">实际消费与行程预估分开记录。${remaining<0?'当前已超出预算，请合理安排后续开销。':'计划周全一点，旅行轻松一点。'}</p></div></div></section>`;}
function checklistPage(){const t=trip(),done=t.checklist.filter(x=>x.done).length,visible=t.checklist.filter(x=>filter==='全部'||x.category===filter);return `<section><div class="page-head"><div><h1>出发前，再检查一下</h1><p class="muted">${e(t.title)} · ${t.days.length} 天 ${Math.max(0,t.days.length-1)} 晚</p></div>${ib('plus','添加准备事项','add-check')}</div><div class="check-layout"><div><div class="check-progress"><div class="row between"><h2>准备完成 ${done} / ${t.checklist.length}</h2>${icon('bag')}</div><div class="progress"><span style="width:${t.checklist.length?done/t.checklist.length*100:0}%"></span></div><p>${t.checklist.length&&done===t.checklist.length?'一切准备就绪，去收集新的风景吧。':'把小事安排好，出发更从容。'}</p></div><div class="tabs filter-tabs" role="group" aria-label="清单分类">${['全部','证件','行李','预约','提醒','其他'].map(f=>`<button type="button" class="tab ${filter===f?'active':''}" aria-pressed="${filter===f}" data-action="filter" data-filter="${f}">${f}</button>`).join('')}</div><div class="checks">${visible.length?visible.map(x=>`<div class="check-row ${x.done?'done':''}"><label class="check-label"><input type="checkbox" data-check-id="${e(x.id)}" ${x.done?'checked':''}><span><strong>${e(x.title)}</strong><p>${e(x.note||x.category)}</p></span></label>${ib('trash',`删除事项${x.title}`,'delete-check',`data-id="${e(x.id)}"`)}</div>`).join(''):empty('这一类还没有事项','按自己的习惯，补上一件准备事项。','check')}</div><div class="action-bar sticky-actions">${btn('添加准备事项','add-check','secondary full','plus')}</div></div><div class="stack"><div class="note">${icon('info')}<div><strong>出发提醒</strong><p class="hint">价格、天气与营业时间，请出发前再次确认。把需要预约的事项提前放进清单。</p></div></div><div class="card flat"><span class="eyebrow">BEFORE YOU GO</span><h2 style="margin:10px 0">准备好，才能放心放空</h2><p class="hint">证件随身带，药品按需备。旅行里最好的事情，往往发生在没有排满的时间里。</p><div class="section-space">${btn('补充系统预设','preset-check','soft full','plus')}</div></div></div></div></section>`;}
function minePage(){const t=trip();return `<section class="profile-layout"><div class="page-head"><div><h1>收藏每一次出发</h1><p class="muted">你的计划，你的旅行节奏。</p></div>${btn('新建旅行','new-trip','primary','plus')}</div><div class="card flat"><div class="row between"><div><span class="eyebrow">CURRENT JOURNEY</span><h2 style="margin-top:8px">${e(t.title)}</h2><p class="hint">${e(t.date)} 出发 · ${e(t.pace)}</p></div><div class="stop-symbol">${icon('mountain')}</div></div><div class="stats"><div class="stat"><strong>${t.days.length}</strong><span>旅行天数</span></div><div class="stat"><strong>${t.days.reduce((n,d)=>n+d.items.length,0)}</strong><span>计划地点</span></div><div class="stat"><strong>${t.members.length}</strong><span>同行伙伴</span></div></div><p class="hint">同行：${t.members.map(m=>e(m.name)).join('、')} · 人均预算 ${money(t.budget)}</p></div><div class="card section-space flat">${[['sparkles','AI 行程服务','统一 DeepSeek 后端，无需用户填写密钥','ai-service'],['calendar','切换旅行',`共 ${state.trips.length} 份计划`,'switch-trip'],['edit','修改旅行名称与预算','只修改名称和预算，不影响已有账单','trip-settings'],['heart','美食与住宿收藏',`${t.favorites.length} 个收藏，留给下次出发`,'favorites'],['share','分享只读行程','分享快照不包含姓名、私人备注与账单','share'],['download','导出完整备份','包含全部旅行和账单，请妥善保管','export'],['upload','导入旅行备份','追加导入，不覆盖现有旅行','import'],['print','打印当前行程','可通过浏览器存成 PDF','print']].map(([symbol,label,note,action])=>`<button type="button" class="menu-row" data-action="${action}">${icon(symbol)}<div class="menu-copy">${label}<p>${note}</p></div>${icon('chevron')}</button>`).join('')}</div><p class="hint section-space">旅策 V0.4 · 数据保存在当前浏览器，清除浏览器数据或更换设备不会自动同步。建议出发前导出备份。在线版当前无需提供 API Key。</p></section>`;}
function readonlyPage(){const s=readonly;return `<div class="readonly-banner">你正在查看一份只读行程快照 · <a href="${e(location.pathname)}">打开我的旅策</a></div><main class="main" style="margin:auto;max-width:760px"><header class="topbar"><span class="brand"><img src="./icon.svg" alt="">旅策</span><span class="pill">只读分享</span></header><div class="page-head"><div><h1>${e(s.city)}，慢一点也很好</h1><p class="muted">${e(s.date)} · ${s.days.length} 天旅行</p></div></div>${s.days.map((d,i)=>`<section class="section-space"><h2 style="margin-bottom:20px">Day ${i+1} · ${e(d.title)}</h2>${d.items.length?d.items.map(x=>`<article class="card flat" style="margin-bottom:12px"><div class="row"><strong class="green">${e(x.time)}</strong><div><h3>${e(x.title)}</h3><p class="hint">${e(x.type)} · 停留 ${x.duration} 分钟</p></div></div></article>`).join(''):empty('自由的一天','留给临时起意的惊喜。')}</section>`).join('')}<p class="hint section-space">这是分享时的行程快照，后续修改不会自动同步。地点、价格和开放时间出发前请再次确认。</p></main>`;}
function render(){maps.dispose();discovery.dispose();if(tab!=='ask')conversation.suspend();if(readonly){app.innerHTML=readonlyPage();return;}day=Math.min(day,trip().days.length-1);app.innerHTML=`<aside class="aside"><div><span class="brand"><img src="./icon.svg" alt="">旅策</span><p>让每一次出发，都有好计划</p></div>${nav(true)}${btn('新建旅行','new-trip','primary','plus')}<div class="aside-footer"><span class="eyebrow">GO A LITTLE FURTHER</span><p>计划可以很周全，<br>旅行也可以很随性。</p></div></aside><main class="main">${topbar()}${({trip:tripPage,ask:()=>conversation.page(),discover:()=>discovery.page(),budget:budgetPage,check:checklistPage,mine:minePage}[tab])()}</main>${nav()}`;if(tab==='trip')maps.mount();if(tab==='ask')conversation.mount();}
function openSheet(title,content){sheet.innerHTML=`<div class="sheet-content"><div class="sheet-head"><h2 id="sheet-title">${e(title)}</h2>${ib('close','关闭对话框','close')}</div>${content}</div>`;if(!sheet.open)sheet.showModal();}
function field(label,name,value='',opts={}){const {type='text',full=false,min,max,step,required=true,placeholder,maxlength}=opts;return `<label class="field ${full?'full':''}">${e(label)}<input type="${type}" name="${name}" value="${e(value)}" ${required?'required':''} ${min!==undefined?`min="${e(min)}"`:''} ${max!==undefined?`max="${e(max)}"`:''} ${step?`step="${e(step)}"`:''} ${placeholder?`placeholder="${e(placeholder)}"`:''} ${maxlength?`maxlength="${e(maxlength)}"`:''}></label>`;}
function select(label,name,options,value='',full=false){return `<label class="field ${full?'full':''}">${e(label)}<select name="${name}">${options.map(o=>{const [v,l]=Array.isArray(o)?o:[o,o];return `<option value="${e(v)}" ${value===v?'selected':''}>${e(l)}</option>`;}).join('')}</select></label>`;}
function formEnd(label='保存',extra=''){return `<p class="form-error" role="alert"></p><div class="form-actions">${btn('取消','close')}${extra}<button class="btn primary" type="submit">${icon('save')}${label}</button></div></form>`;}
function newTrip(){openSheet('下一站，想去哪里？',`<p class="hint" style="margin-bottom:20px">杭州、成都、大理提供本地灵感模板，其他城市从空白计划开始。新建不会覆盖已有旅行。</p><div style="margin-bottom:18px">${btn('想要专属路线？使用 AI 规划','ai-start','soft full','sparkles')}</div><form data-form="trip"><div class="form-grid">${field('目的地','city','杭州',{full:true,maxlength:30})}${field('出发日期','date',localDate(7),{type:'date',min:localDate(),max:'2100-12-31'})}${field('出行天数','count',3,{type:'number',min:1,max:30})}${field('同行人（用逗号分隔）','members','我，同伴',{full:true,maxlength:200})}${field('人均总预算（元）','budget','2000',{type:'number',min:.01,max:99999999.99,step:'.01'})}${select('旅行节奏','pace',['慢逛休闲','紧凑打卡'],'慢逛休闲')}<div class="field full"><span>这次想体验什么？</span><div class="choices">${['自然风光','当地美食','人文古迹','博物馆','亲子乐园'].map((x,i)=>`<label class="choice"><input type="checkbox" name="pref" value="${x}" ${i<2?'checked':''}>${x}</label>`).join('')}</div></div></div>${formEnd('生成旅行计划')}`);}
function editStop(id){const item=trip().days[day].items.find(x=>x.id===id);openSheet(item?'编辑行程地点':'添加一个想去的地方',`<form data-form="stop" data-id="${e(id||'')}"><div class="form-grid">${field('地点名称','title',item?.title||'',{full:true,maxlength:80,placeholder:'例如：西湖 · 断桥残雪'})}${field('开始时间','time',item?.time||'09:00',{type:'time'})}${field('停留时间（分钟）','duration',item?.duration||60,{type:'number',min:5,max:720})}${select('地点类型','type',['景点','餐饮','住宿','交通','体验','其他'],item?.type||'景点')}${field('预计人均费用（元）','cost',(item?.cost||0)/100,{type:'number',min:0,max:99999999.99,step:'.01'})}<label class="field full">备注<textarea name="note" maxlength="500" placeholder="想做什么？有没有需要提前预约的事？">${e(item?.note||'')}</textarea></label></div>${formEnd('保存地点',item?btn('删除','delete-stop','danger','trash',`data-id="${e(id)}"`):'')}`);}
function expenseForm(id){const t=trip(),x=t.expenses.find(x=>x.id===id);openSheet(x?'编辑这笔消费':'记下一笔共同开销',`<form data-form="expense" data-id="${e(id||'')}"><div class="form-grid">${field('买了什么？','title',x?.title||'',{full:true,maxlength:80,placeholder:'例如：杭帮菜午餐'})}${field('金额（元）','amount',x?x.cents/100:'',{type:'number',min:.01,max:99999999.99,step:'.01'})}${select('消费类型','type',['餐饮','住宿','交通','门票','购物','其他'],x?.type||'餐饮')}${select('付款人','payer',t.members.map(m=>[m.id,m.name]),x?.payer||t.members[0].id)}${field('消费日期','date',x?.date||localDate(),{type:'date',min:'2000-01-01',max:'2100-12-31'})}<div class="field full"><span>参与分摊的人</span><div class="choices">${t.members.map(m=>`<label class="choice"><input type="checkbox" name="participant" value="${e(m.id)}" ${!x||x.participants.includes(m.id)?'checked':''}>${e(m.name)}</label>`).join('')}</div></div></div><div class="preview-split" id="split-preview">填写金额后，自动预览每人分摊。</div>${formEnd('保存消费',x?btn('删除','delete-expense','danger','trash',`data-id="${e(id)}"`):'')}`);updateSplit();}
function updateSplit(){const f=sheet.querySelector('[data-form="expense"]');if(!f)return;const amount=f.elements.amount.value,people=[...f.querySelectorAll('[name="participant"]:checked')].map(x=>x.value),preview=sheet.querySelector('#split-preview');try{const cents=toCents(amount);if(!people.length){preview.textContent='请至少选择一位参与人';return;}const n=Math.floor(cents/people.length),rem=cents%people.length;preview.innerHTML=`均分预览 · ${people.length} 人参与<br>${people.map((id,i)=>`${e(trip().members.find(m=>m.id===id).name)} ${money(n+(i<rem?1:0))}`).join(' · ')}`;}catch{preview.textContent='填写有效金额后，自动预览每人分摊。';}}
function checkForm(){openSheet('添加准备事项',`<form data-form="check"><div class="form-grid">${field('准备什么？','title','',{full:true,maxlength:80,placeholder:'例如：预约博物馆门票'})}${select('分类','category',['证件','行李','预约','提醒','其他'],'其他',true)}${field('补充说明','note','',{full:true,required:false,maxlength:500})}</div>${formEnd('加入清单')}`);}
function showSettle(){const l=ledger(trip());openSheet('大家的旅行账本',`${l.transfers.length?l.transfers.map(x=>`<div class="settle-row"><strong>${e(x.from)} ${icon('arrow',true)} ${e(x.to)}</strong><strong>${money(x.cents)}</strong></div>`).join(''):`<div class="note">${icon('save')}当前无需转账结算</div>`}<div class="section-space">${l.balances.map(m=>`<div class="split-member"><strong>${e(m.name)}</strong><span class="${m.net>=0?'green':'amber'}">${m.net>=0?'应收':'应付'} ${money(Math.abs(m.net))}</span><small>已付 ${money(m.paid)} · 应承担 ${money(m.owed)}</small></div>`).join('')}</div><p class="hint section-space">总支出 ${money(l.total)}，净差额合计 ${money(l.balances.reduce((s,m)=>s+m.net,0))}。这是转账建议，不会发起付款。</p><div class="form-actions">${btn('知道了','close','primary full')}</div>`);}
function share(){const value=encodeShare(trip());if(value.length>12000){toast('行程较长，请通过打印或备份分享');return;}const url=`${location.origin}${location.pathname}#share=${value}`;openSheet('把期待，分享给同行的人',`<div class="note">${icon('share')}<div><strong>${e(trip().title)} · ${trip().days.length} 天</strong><p class="hint">只包含地点、时间和类型，不包含成员姓名、账单、私人备注。</p></div></div><label class="field section-space">只读快照链接<div class="share-box"><textarea readonly id="share-url" aria-label="只读快照链接">${e(url)}</textarea></div></label><p class="hint section-space">链接里的内容是当前快照，之后的修改不会同步，已发出的快照无法远程撤回。接收人还需要有本站访问权限。</p><div class="form-actions">${btn('关闭','close')}${btn('复制链接','copy-share','primary','copy')}</div>`);}
function favorites(){const t=trip();openSheet('美食与住宿收藏',`<div class="favorite-grid">${t.favorites.length?t.favorites.map(x=>`<article class="card flat"><span class="pill">${e(x.type)}</span><h3 style="margin-top:12px">${e(x.title)}</h3><p>${e(x.note||'留给下一次出发。')}</p>${btn('加入当天行程','favorite-stop','soft full','plus',`data-id="${e(x.id)}"`)}${btn('删除收藏','delete-favorite','text','trash',`data-id="${e(x.id)}"`)}</article>`).join(''):empty('先把喜欢的地方收藏起来','一家小馆、一间民宿，或一段想走的路。','heart')}</div><div class="section-space">${btn('添加收藏','add-favorite','primary full','plus')}</div>`);}
function exportBackup(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`旅策备份-${localDate()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('已导出全部旅行备份，请妥善保管');}
function selectPlace(place,id=null,type=null){
  editStop(id);const form=sheet.querySelector('[data-form="stop"]');form.elements.title.value=place.name;form._amapPlace=place;if(type)form.elements.type.value=type;
  const old=form.elements.note.value;form.elements.note.value=((old?old+'；':'')+place.address).slice(0,500);toast('已选中高德地点，确认时间后保存');
}
const maps=createMapFeature({sheet,e,btn,icon,openSheet,field,toast,currentTrip:trip,currentDay:()=>day,onPick:selectPlace,rerender:render});
const discovery=createDiscovery({e,btn,icon,currentTrip:trip,currentDay:()=>day,onPick:(place,type)=>selectPlace(place,null,type),toast});
const conversation=createConversation({e,btn,icon,toast,currentTrip:trip,currentDay:()=>day,rerender:render,
  addTrip:n=>{if(state.trips.length>=30)throw Error('最多保存 30 份旅行');state.trips.push(n);state.activeId=n.id;day=0;tab='trip';filter='全部';persist('AI 草稿已保存为新旅行');window.scrollTo({top:0,behavior:'instant'});},
  replaceTrip:(updated,index)=>{const i=state.trips.findIndex(t=>t.id===updated.id);if(i<0)throw Error('原旅行不存在');state.trips[i]=updated;day=index;tab='trip';persist('当天行程已更新，账单和清单保留');window.scrollTo({top:0,behavior:'instant'});}
});
function openConversation(kind='new',seed=''){sheet.close();conversation.start(kind,seed);tab='ask';render();window.scrollTo({top:0,behavior:'instant'});}
const actions={
  ...maps.actions,
  ...conversation.actions,
  ...discovery.actions,
  'ai-start':()=>openConversation('new'),'ai-service':()=>openConversation('new'),'ask-open':()=>openConversation('new'),
  'ask-ai-adjust':()=>openConversation('adjust','请帮我检查和调整当天安排，先确认我已经完成哪些活动。'),
  'discovery-type':el=>{discovery.actions['discovery-type'](el);render();},
  nav:el=>{tab=el.dataset.tab;ordering=false;render();window.scrollTo({top:0,behavior:'instant'});},
  day:el=>{day=Number(el.dataset.day);maps.setScope('day');render();},filter:el=>{filter=el.dataset.filter;render();},close:()=>sheet.close(),'new-trip':newTrip,
  'add-stop':()=>editStop(), 'edit-stop':el=>editStop(el.dataset.id),order:()=>{ordering=!ordering;render();if(ordering)toast('用上下按钮调整顺序，修改即时保存');},
  move:el=>{const a=trip().days[day].items,i=a.findIndex(x=>x.id===el.dataset.id),j=i+Number(el.dataset.dir);if(i>=0&&j>=0&&j<a.length){[a[i],a[j]]=[a[j],a[i]];persist();}},
  'delete-stop':el=>{const d=trip().days[day];d.items=d.items.filter(x=>x.id!==el.dataset.id);sheet.close();persist('地点已删除');},
  'add-expense':()=>expenseForm(),'edit-expense':el=>expenseForm(el.dataset.id),'delete-expense':el=>{trip().expenses=trip().expenses.filter(x=>x.id!==el.dataset.id);sheet.close();persist('消费已删除，结算已更新');},
  'add-check':checkForm,'delete-check':el=>{trip().checklist=trip().checklist.filter(x=>x.id!==el.dataset.id);persist('事项已删除');},
  'preset-check':()=>{let added=0;for(const x of makeTrip().checklist)if(!trip().checklist.some(y=>y.title===x.title)){trip().checklist.push(x);added++;}persist(added?`已补充 ${added} 项准备事项`:'预设事项都在清单里了');},
  settle:showSettle,'budget-info':()=>openSheet('费用怎么算？',`<div class="dialog-copy"><p>每笔消费只由被选中的参与人均分。付款人可以先垫付，最终按「已付款 − 应承担费用」计算应收或应付。</p><p>以「分」为单位计算，不能整除的尾差按参与人的固定顺序补分，确保每笔分摊总额和原始金额一致。</p><p>行程中的预计费用不计入实际账单。结算清单只供核对，不会自动转账。</p></div><div class="form-actions">${btn('明白了','close','primary full')}</div>`),
  share,'copy-share':async()=>{const text=sheet.querySelector('#share-url');try{await navigator.clipboard.writeText(text.value);toast('只读行程链接已复制');}catch{text.select();toast('请长按链接或使用 Ctrl+C 手动复制');}},
  'switch-trip':()=>openSheet('切换旅行',`${state.trips.map(t=>`<button type="button" class="trip-choice ${trip().id===t.id?'selected':''}" data-action="choose-trip" data-id="${e(t.id)}"><div><strong>${e(t.title)}</strong><p class="hint">${e(t.date)} · ${t.days.length} 天 · ${t.members.length} 人</p></div>${icon(trip().id===t.id?'save':'chevron')}</button>`).join('')}<div class="section-space">${btn('规划新的出发','new-trip','primary full','plus')}</div>`),
  'choose-trip':el=>{state.activeId=el.dataset.id;day=0;filter='全部';sheet.close();tab='trip';persist('已切换旅行');window.scrollTo({top:0,behavior:'instant'});},
  'trip-settings':()=>openSheet('旅行名称与预算',`<form data-form="settings"><div class="form-grid">${field('旅行名称','title',trip().title,{full:true,maxlength:80})}${field('人均预算（元）','budget',trip().budget/100,{type:'number',min:.01,step:'.01',max:99999999.99,full:true})}</div><p class="hint section-space">同行成员在创建时确定，避免修改后影响已有账目的分摊。不同成员的旅行请新建一份计划。</p>${formEnd()}`),
  export:exportBackup,import:()=>{const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{const file=input.files[0];if(!file)return;try{if(file.size>2000000)throw new Error('备份文件最多 2 MB');const imported=parseBackup(await file.text());const additions=imported.trips.filter(t=>!state.trips.some(x=>x.id===t.id));if(state.trips.length+additions.length>30)throw new Error('最多保存 30 份旅行，请拆分备份');state.trips.push(...additions);persist(additions.length?`已追加 ${additions.length} 份旅行`:'这些旅行已存在，未覆盖当前内容');}catch(err){toast(err.message||'文件无法读取，当前旅行未修改');}};input.click();},
  print:()=>{tab='trip';render();window.print();},favorites,
  'add-favorite':()=>openSheet('把喜欢的地方留下',`<form data-form="favorite"><div class="form-grid">${field('名称','title','',{full:true,maxlength:80})}${select('类型','type',['餐饮','住宿','景点','体验'],'餐饮',true)}${field('备注','note','',{full:true,required:false,maxlength:500})}</div>${formEnd('保存收藏')}`),
  'favorite-stop':el=>{const x=trip().favorites.find(x=>x.id===el.dataset.id);sheet.close();tab='trip';render();editStop();const f=sheet.querySelector('form');f.elements.title.value=x.title;f.elements.type.value=x.type;f.elements.note.value=x.note;},
  'delete-favorite':el=>{trip().favorites=trip().favorites.filter(x=>x.id!==el.dataset.id);persist();favorites();}
};
document.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(!el||el.disabled)return;const fn=actions[el.dataset.action];if(fn&&!readonly){Promise.resolve(fn(el)).catch(()=>toast('操作暂未完成，请重试'));}});
document.addEventListener('change',event=>{const el=event.target;if(readonly)return;if(el.dataset.checkId){const x=trip().checklist.find(x=>x.id===el.dataset.checkId);if(x){x.done=el.checked;persist();}}if(el.closest('[data-form="expense"]'))updateSplit();});
sheet.addEventListener('input',()=>updateSplit());
sheet.addEventListener('click',event=>{if(event.target===sheet){const r=sheet.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)sheet.close();}});
sheet.addEventListener('submit',event=>{
  event.preventDefault();const f=event.target;if(!f.reportValidity())return;if(maps.handleSubmit(f))return;const data=new FormData(f),v=name=>String(data.get(name)||'').trim();
  try{
    const t=trip();switch(f.dataset.form){
      case 'trip':{if(state.trips.length>=30)throw new Error('最多保存 30 份旅行');if(v('date')<localDate())throw new Error('新旅行的出发日期不能早于今天');const names=v('members').split(/[,，、\n]/).map(x=>x.trim()).filter(Boolean);const n=makeTrip({city:v('city'),date:v('date'),count:Number(v('count')),names,budget:toCents(v('budget')),pace:v('pace'),preferences:data.getAll('pref')});state.trips.push(n);state.activeId=n.id;day=0;tab='trip';filter='全部';break;}
      case 'stop':{const rawCost=v('cost'),cost=Number(rawCost)===0?0:toCents(rawCost);const x={id:f.dataset.id||uid(),title:v('title'),time:v('time'),duration:Number(v('duration')),type:v('type'),cost,note:v('note')};if(!x.title)throw new Error('请填写地点名称');if(!Number.isInteger(x.duration)||x.duration<5||x.duration>720)throw new Error('停留时间为 5–720 分钟');const items=t.days[day].items,idx=items.findIndex(y=>y.id===x.id);const selected=f._amapPlace||(idx>=0&&items[idx].title===x.title?items[idx].place:null);if(validPlace(selected)&&selected.name===x.title)x.place=selected;if(idx>=0)items[idx]=x;else{if(items.length>=50)throw new Error('每天最多安排 50 个地点');items.push(x);}break;}
      case 'expense':{const x={id:f.dataset.id||uid(),title:v('title'),type:v('type'),cents:toCents(v('amount')),date:v('date'),payer:v('payer'),participants:data.getAll('participant')};if(!x.title)throw new Error('请填写消费名称');if(!x.participants.length)throw new Error('请至少选择一位分摊人员');const idx=t.expenses.findIndex(y=>y.id===x.id);if(idx>=0)t.expenses[idx]=x;else{if(t.expenses.length>=2000)throw new Error('单份旅行最多记录 2,000 笔消费');t.expenses.push(x);}break;}
      case 'check':if(t.checklist.length>=200)throw new Error('单份清单最多保存 200 项');if(!v('title'))throw new Error('请填写事项名称');t.checklist.push({id:uid(),title:v('title'),note:v('note'),category:v('category'),done:false});break;
      case 'settings':if(!v('title'))throw new Error('请填写旅行名称');{const b=toCents(v('budget'));t.title=v('title');t.budget=b;}break;
      case 'favorite':if(t.favorites.length>=100)throw new Error('单份旅行最多保存 100 个收藏');if(!v('title'))throw new Error('请填写收藏名称');t.favorites.push({id:uid(),title:v('title'),type:v('type'),note:v('note')});break;
    }
    sheet.close();persist(f.dataset.form==='trip'?'旅行计划已准备好，随时可以调整':'已保存');
  }catch(err){f.querySelector('.form-error').textContent=err.message||'请检查输入后重试';}
});
document.addEventListener('submit',event=>{
  const form=event.target;if(form.closest('#sheet'))return;event.preventDefault();if(readonly||!form.reportValidity())return;
  if(conversation.handleSubmit(form,event.submitter?.dataset.intent||'talk'))return;discovery.handleSubmit(form);
});
render();
if(!readonly&&!recovery)persist();
if(recovery)toast('本机记录或分享内容无法读取，已载入示例；原记录暂未覆盖');
